<h1><?= $host?'Edit Host':'Add Host' ?></h1><form class='form-card' method='POST' action='<?= $action ?>'><?= csrf_field() ?><?php if(!$host): ?><label>User</label><select name='user_id'><?php foreach($users as $u): ?><option value='<?= $u['user_id'] ?>'><?= e($u['full_name']) ?> - <?= e($u['email']) ?></option><?php endforeach; ?></select><?php endif; ?><label>Company</label><input name='company_name' value='<?= e($host['company_name']??'') ?>' required><label>Contact</label><input name='contact_person' value='<?= e($host['contact_person']??'') ?>' required><label>License</label><input name='license_number' value='<?= e($host['license_number']??'') ?>'><label><input type='checkbox' name='is_verified' <?= ($host['is_verified']??0)?'checked':'' ?>> Verified</label><button class='btn'>Save</button></form>
